}

fn backup_file(path: &Path) -> Result<PathBuf, std::io::Error> {
    let backup_path = path.with_extension(
        path.extension()
            .map(|e| format!("{}.bk", e.to_string_lossy()))
            .unwrap_or_else(|| "bk".to_string()),
    );
    std::fs::copy(path, &backup_path)?;
    Ok(backup_path)
}

fn apply_transform(s: &str, transform: &Option<ReplaceTransform>) -> String {
    match transform {
        None => s.to_string(),
        Some(ReplaceTransform::Upper) => s.to_uppercase(),
        Some(ReplaceTransform::Lower) => s.to_lowercase(),
        Some(ReplaceTransform::Ascii) => unidecode::unidecode(s),
    }
}

fn compute_new_name(
    regex: &Regex,
    filename: &str,
    replacement: &str,
    limit: usize,
    transform: &Option<ReplaceTransform>,
) -> Option<String> {
    // Build replacement with transform applied
    let new_name = if limit == 0 {
        regex.replace_all(filename, |caps: &regex::Captures| {
            let replaced = caps.expand_str_to_string(replacement);
            apply_transform(&replaced, transform)
        }).to_string()
    } else {
        let mut count = 0;
        regex.replacen(filename, limit, |caps: &regex::Captures| {
            count += 1;
            let replaced = caps.expand_str_to_string(replacement);
            apply_transform(&replaced, transform)
        }).to_string()
    };

    if new_name != filename {
        Some(new_name)
    } else {
        None
    }
}

fn process_paths_regex(
    regex: &Regex,
    replacement: &str,
    paths: &[PathBuf],
    force: bool,
    backup: bool,
    silent: bool,
    use_color: bool,
    dump: bool,
    no_dump: bool,
    dump_prefix: &str,
    replace_limit: usize,
    replace_transform: &Option<ReplaceTransform>,
    include_dirs: bool,
    recursive: bool,
    max_depth: Option<usize>,
    hidden: bool,
) {
    let is_dry_run = !force;

    if !silent {
        if is_dry_run {
            if use_color {
                println!("{}", bold("This is a DRY-RUN"));
            } else {
                println!("This is a DRY-RUN");
            }
        }
    }

    let mut operations: Vec<Operation> = Vec::new();

    // Collect all paths to process
    let mut all_paths: Vec<PathBuf> = Vec::new();

    for path in paths {
        if recursive {
            let depth = max_depth.unwrap_or(usize::MAX);
            let walker = WalkDir::new(path)
                .max_depth(depth)
                .min_depth(1);

            for entry in walker {
                match entry {
                    Ok(e) => {
                        let ep = e.path().to_path_buf();
                        let is_hidden = ep.file_name()
                            .and_then(|n| n.to_str())
                            .map(|n| n.starts_with('.'))
                            .unwrap_or(false);
                        if !hidden && is_hidden {
                            continue;
                        }
                        if e.file_type().is_dir() {
                            if include_dirs {
                                all_paths.push(ep);
                            }
                        } else {
                            all_paths.push(ep);
                        }
                    }
                    Err(_) => {}
                }
            }
        } else {
            if path.is_dir() {
                if include_dirs {
                    all_paths.push(path.clone());
                }
            } else {
                all_paths.push(path.clone());
            }
        }
    }

    // Sort paths - process deeper paths first to avoid conflicts
    // Actually, let's process in the order they were found
    // but for dirs, we need to process deepest first

    for path in &all_paths {
        let filename = match path.file_name().and_then(|n| n.to_str()) {
            Some(f) => f,
            None => continue,
        };

        let new_filename = match compute_new_name(regex, filename, replacement, replace_limit, replace_transform) {
            Some(n) => n,
            None => continue,
        };

        let parent = path.parent().unwrap_or_else(|| Path::new(""));
        let new_path = parent.join(&new_filename);

