                    match backup_file(path) {
                        Ok(backup_path) => {
                            if use_color {
                                print!("{} ", bold("Info: "));
                                println!(" Backup created - {}", dark_gray(&format!("{} -> {}", path.display(), backup_path.display())));
                            } else {
                                println!("Info:  Backup created - {} -> {}", path.display(), backup_path.display());
                            }
                        }
                        Err(_) => {}
                    }
                }

                // Show the operation
                print_operation_color(path, &new_path, filename, &new_filename, regex, replacement, replace_limit, use_color);
            } else {
                // Dry run - just show
                print_operation_color(path, &new_path, filename, &new_filename, regex, replacement, replace_limit, use_color);
            }
        }

        if force {
            let _ = rename_file(path, &new_path);
        }

        operations.push(op);
    }

    // Handle dump
    let should_dump = if no_dump {
        false
    } else if dump {
        true
    } else {
        force // Only dump when actually making changes
    };

    if should_dump && !operations.is_empty() {
        write_dump(dump_prefix, &operations);
    }
}

fn print_operation_color(
    src_path: &Path,
    dst_path: &Path,
    src_filename: &str,
    dst_filename: &str,
    regex: &Regex,
    replacement: &str,
    limit: usize,
    use_color: bool,
) {
    if use_color {
        let src_parent = src_path.parent()
            .map(|p| format!("{}/", p.display()))
            .unwrap_or_default();
        let dst_parent = dst_path.parent()
            .map(|p| format!("{}/", p.display()))
            .unwrap_or_default();

        let colored_src = format!("{}{}", dark_gray(&src_parent), dark_gray(src_filename));
        let colored_dst_fn = colorize_filename_dest(regex, src_filename, replacement, limit);
        let colored_dst = format!("{}{}", green(&dst_parent), colored_dst_fn);

        println!("{} -> {}", colored_src, colored_dst);
    } else {
        println!("{} -> {}", src_path.display(), dst_path.display());
    }
}

fn write_dump(prefix: &str, operations: &[Operation]) {
    let now = Local::now();
    let filename = format!("{}{}", prefix, now.format("%Y-%m-%d_%H%M%S"));
    let dump = DumpFile {
        date: now.format("%Y-%m-%d %H:%M:%S").to_string(),
        operations: operations.iter().map(|op| Operation {
            source: op.source.clone(),
            target: op.target.clone(),
        }).collect(),
    };

    if let Ok(json) = serde_json::to_string_pretty(&dump) {
        let _ = std::fs::write(&filename, json);
    }
}

fn process_from_file(
    dumpfile: &Path,
    force: bool,
    backup: bool,
    silent: bool,
    use_color: bool,
    dump: bool,
    no_dump: bool,
    dump_prefix: &str,
    undo: bool,
) {
    let content = match std::fs::read_to_string(dumpfile) {
        Ok(c) => c,
        Err(e) => {
            eprintln!("Error: {}", e);
            return;
        }
    };

    let dump_data: DumpFile = match serde_json::from_str(&content) {
        Ok(d) => d,
        Err(e) => {
            eprintln!("Error: {}", e);
            return;
        }
    };

    let is_dry_run = !force;

    if !silent {
        if is_dry_run {
            if use_color {
                println!("{}", bold("This is a DRY-RUN"));
            } else {
                println!("This is a DRY-RUN");
            }
        }
    }

    let mut new_operations: Vec<Operation> = Vec::new();

    for op in &dump_data.operations {
        let (src, dst) = if undo {
            (&op.target, &op.source)
        } else {
            (&op.source, &op.target)
        };

        let src_path = Path::new(src);
        let dst_path = Path::new(dst);

        if !silent {
            if force {
                if backup {
                    if let Ok(backup_path) = backup_file(src_path) {
                        if use_color {
                            print!("{} ", bold("Info: "));
                            println!(" Backup created - {}", dark_gray(&format!("{} -> {}", src_path.display(), backup_path.display())));
                        } else {
                            println!("Info:  Backup created - {} -> {}", src_path.display(), backup_path.display());
                        }
                    }
                }
            }

            if use_color {
                let src_parent = src_path.parent()
                    .map(|p| format!("{}/", p.display()))
                    .unwrap_or_default();
                let dst_parent = dst_path.parent()
                    .map(|p| format!("{}/", p.display()))
                    .unwrap_or_default();
                let src_filename = src_path.file_name()
                    .and_then(|n| n.to_str())
                    .unwrap_or("");
                let dst_filename = dst_path.file_name()
                    .and_then(|n| n.to_str())
                    .unwrap_or("");

                println!("{}{} -> {}{}",
                    dark_gray(&src_parent), dark_gray(src_filename),
                    green(&dst_parent), green(dst_filename)
                );
            } else {
                println!("{} -> {}", src, dst);
            }
        }

        if force {
            let _ = rename_file(src_path, dst_path);
        }

        new_operations.push(Operation {
            source: src.clone(),
            target: dst.clone(),
        });
    }

    let should_dump = if no_dump { false } else if dump { true } else { force };
    if should_dump && !new_operations.is_empty() {
        write_dump(dump_prefix, &new_operations);
    }
}

fn to_ascii_filename(filename: &str) -> String {
    unidecode::unidecode(filename)
}

fn process_paths_to_ascii(
    paths: &[PathBuf],
    force: bool,
    backup: bool,
    silent: bool,
    use_color: bool,
    dump: bool,
    no_dump: bool,
    dump_prefix: &str,
    include_dirs: bool,
    recursive: bool,
    max_depth: Option<usize>,
    hidden: bool,
) {
    let is_dry_run = !force;

    if !silent {
        if is_dry_run {
            if use_color {
                println!("{}", bold("This is a DRY-RUN"));
            } else {
                println!("This is a DRY-RUN");
            }
        }
    }

    let mut operations: Vec<Operation> = Vec::new();
    let mut all_paths: Vec<PathBuf> = Vec::new();

    for path in paths {
        if recursive {
            let depth = max_depth.unwrap_or(usize::MAX);
            let walker = WalkDir::new(path)
                .max_depth(depth)
                .min_depth(1);

            for entry in walker {
                match entry {
                    Ok(e) => {
                        let ep = e.path().to_path_buf();
                        let is_hidden = ep.file_name()
                            .and_then(|n| n.to_str())
                            .map(|n| n.starts_with('.'))
                            .unwrap_or(false);
                        if !hidden && is_hidden {
                            continue;
                        }
                        if e.file_type().is_dir() {
                            if include_dirs {
                                all_paths.push(ep);
                            }
                        } else {
                            all_paths.push(ep);
                        }
                    }
                    Err(_) => {}
                }
            }
        } else {
            if path.is_dir() {
                if include_dirs {
                    all_paths.push(path.clone());
                }
            } else {
                all_paths.push(path.clone());
            }
        }
    }

    for path in &all_paths {
        let filename = match path.file_name().and_then(|n| n.to_str()) {
            Some(f) => f,
            None => continue,
        };

        let new_filename = to_ascii_filename(filename);
        if new_filename == filename {
            continue;
        }

        let parent = path.parent().unwrap_or_else(|| Path::new(""));
        let new_path = parent.join(&new_filename);

        if !silent {
            if use_color {
                let src_parent = path.parent()
                    .map(|p| format!("{}/", p.display()))
                    .unwrap_or_default();
                let dst_parent = new_path.parent()
                    .map(|p| format!("{}/", p.display()))
                    .unwrap_or_default();

                println!("{}{} -> {}{}",
                    dark_gray(&src_parent), dark_gray(filename),
                    green(&dst_parent), green(&new_filename)
                );
            } else {
                println!("{} -> {}", path.display(), new_path.display());
            }
        }

        if force {
            if backup {
                let _ = backup_file(path);
            }
            let _ = rename_file(path, &new_path);
        }

        operations.push(Operation {
            source: path.to_string_lossy().to_string(),
            target: new_path.to_string_lossy().to_string(),
        });
    }

    let should_dump = if no_dump { false } else if dump { true } else { force };
    if should_dump && !operations.is_empty() {
        write_dump(dump_prefix, &operations);
    }
}

// Helper trait for Captures
trait CapturesExt {
    fn expand_str_to_string(&self, replacement: &str) -> String;
}

impl<'t> CapturesExt for regex::Captures<'t> {
    fn expand_str_to_string(&self, replacement: &str) -> String {
        let mut dst = String::new();
        self.expand(replacement, &mut dst);
        dst
    }
}

fn main() {
    let cli = Cli::parse();

    match cli.command {
        Commands::Regex {
            expression,
            replacement,
            paths,
            dry_run: _,
            force,
            backup,
            silent,
            color,
            dump,
            dump_prefix,
            no_dump,
            replace_limit,
            replace_transform,
            include_dirs,
            recursive,
            max_depth,
            hidden,
        } => {
            let regex = match Regex::new(&expression) {
                Ok(r) => r,
                Err(e) => {
                    println!("Error: Bad expression provided\n\n{}", e);
                    std::process::exit(1);
                }
            };

            let use_col = use_color(&color);

            process_paths_regex(
                &regex,
                &replacement,
                &paths,
                force,
                backup,
                silent,
                use_col,
                dump,
                no_dump,
                &dump_prefix,
                replace_limit,
                &replace_transform,
                include_dirs,
                recursive,
                max_depth,
                hidden,
            );
        }
        Commands::FromFile {
            dumpfile,
            dry_run: _,
            force,
            backup,
            silent,
            color,
            dump,
            dump_prefix,
            no_dump,
            undo,
        } => {
            let use_col = use_color(&color);
            process_from_file(
                &dumpfile,
                force,
                backup,
                silent,
                use_col,
                dump,
                no_dump,
                &dump_prefix,
                undo,
            );
        }
        Commands::ToAscii {
            paths,
            dry_run: _,
            force,
            backup,
            silent,
            color,
            dump,
            dump_prefix,
            no_dump,
            include_dirs,
            recursive,
            max_depth,
            hidden,
        } => {
            let use_col = use_color(&color);
            process_paths_to_ascii(
                &paths,
                force,
                backup,
                silent,
                use_col,
                dump,
                no_dump,
                &dump_prefix,
                include_dirs,
                recursive,
                max_depth,
                hidden,
            );
        }
    }
}
