}

fn green(s: &str) -> String {
    format!("\x1b[32m{}\x1b[0m", s)
}

fn bold_red(s: &str) -> String {
    format!("\x1b[1;31m{}\x1b[0m", s)
}

fn dark_gray(s: &str) -> String {
    format!("\x1b[38;5;8m{}\x1b[0m", s)
}

fn bold_colored(s: &str, color: bool) -> String {
    if color { bold(s) } else { s.to_string() }
}

/// Build colorized filename for destination (result)
/// Using the algorithm: find match positions in source, apply replacements,
/// and color the result based on the original match positions.
fn colorize_filename_dest(
    regex: &Regex,
    source: &str,
    replacement: &str,
    limit: usize,
) -> String {
    let mut output = String::new();
    let mut last_source_end = 0usize;
    let mut count = 0usize;
    let actual_limit = if limit == 0 { usize::MAX } else { limit };

    // Collect all matches
    let matches: Vec<_> = regex.find_iter(source).collect();

    // Find which matches are replaced
    let replaced_count = matches.len().min(actual_limit);

    // We need to build the result string and track positions
    // Build the full result string first to know what chars are at each result position
    let result = if limit == 0 {
        regex.replace_all(source, replacement).to_string()
    } else {
        regex.replacen(source, limit, replacement).to_string()
    };

    // Now build colored output using result string positions
    let mut result_pos = 0usize;  // current position in result string
    let mut source_pos = 0usize;  // current position in source string

    for (idx, m) in matches.iter().enumerate() {
        let is_replaced = idx < replaced_count;

        // Non-match section before this match: source[source_pos..m.start()]
        let non_match = &source[source_pos..m.start()];
        if !non_match.is_empty() {
            // Apply two-groups rule to non-match section
            let match_text = if idx > 0 { 
                matches[idx-1].as_str() 
            } else { 
                "" 
            };
            let (g1, g2) = split_non_match_two_groups(non_match, match_text);
            if !g1.is_empty() {
                output += &green(g1);
                result_pos += g1.len();
            }
            if !g2.is_empty() {
                output += &green(g2);
                result_pos += g2.len();
            }
            source_pos = m.start();
        }

        if is_replaced {
            // Compute the actual replacement (with captures)
            let actual_repl = compute_replacement(regex, m.as_str(), replacement);

            // Find suffix in source after this match
            let next_match_start = if idx + 1 < matches.len() {
                matches[idx + 1].start()
            } else {
                source.len()
            };
            let suffix_in_source = &source[m.end()..next_match_start];

            // Compute n = common prefix length between actual_repl and suffix_in_source
            let n = common_prefix_len(&actual_repl, suffix_in_source);

            // Green prefix (common prefix)
            if n > 0 {
                let green_prefix = &result[result_pos..result_pos + n];
                output += &green(green_prefix);
                result_pos += n;
            }

            // Red replacement
            if !actual_repl.is_empty() {
                let red_repl = &result[result_pos..result_pos + actual_repl.len()];
                output += &bold_red(red_repl);
                result_pos += actual_repl.len();
            }

            // Advance source past match + n chars of suffix already consumed
            source_pos = m.end() + n;
        } else {
            // Non-replaced match: show as one green block
            let match_len = m.as_str().len();
            let match_in_result = &result[result_pos..result_pos + match_len];
            output += &green(match_in_result);
            result_pos += match_len;
            source_pos = m.end();
        }
    }

    // Remaining source after all matches
    let remaining = &source[source_pos..];
    if !remaining.is_empty() {
        // Apply two-groups rule
        let last_match_text = if !matches.is_empty() {
            matches[matches.len() - 1].as_str()
        } else {
            ""
        };
        let (g1, g2) = split_non_match_two_groups(remaining, last_match_text);
        if !g1.is_empty() {
            output += &green(g1);
            result_pos += g1.len();
        }
        if !g2.is_empty() {
            output += &green(g2);
            result_pos += g2.len();
        }
    }

    let _ = result_pos; // suppress warning
    output
}

fn compute_replacement(regex: &Regex, matched: &str, replacement: &str) -> String {
    // Apply capture groups in replacement
    let source_piece = matched;
    let result = regex.replacen(source_piece, 1, replacement);
    result.to_string()
}

fn common_prefix_len(a: &str, b: &str) -> usize {
    a.chars().zip(b.chars()).take_while(|(x, y)| x == y).count()
}

/// Split a non-match section into two groups for coloring.
/// Group 1: longest prefix where each char is forward-consecutive in the last match
/// Group 2: the rest (as one block)
fn split_non_match_two_groups<'a>(section: &'a str, last_match: &str) -> (&'a str, &'a str) {
    if last_match.is_empty() || section.is_empty() {
        return ("", section);
    }

    let chars: Vec<char> = section.chars().collect();
    let match_chars: Vec<char> = last_match.chars().collect();

    let mut current_pos: Option<usize> = None;
    let mut group1_len = 0usize;
    let mut char_byte_pos = 0usize;

    for (i, &c) in chars.iter().enumerate() {
        // Find position of c in match_chars
        let found_pos = match_chars.iter().position(|&mc| mc == c);

        if let Some(pos) = found_pos {
            // Check if this position is forward from current
            let ok = match current_pos {
                None => true,
                Some(cp) => pos > cp,
            };
            if ok {
                current_pos = Some(pos);
                let char_len = c.len_utf8();
                char_byte_pos += char_len;
                group1_len = char_byte_pos;
                let _ = i;
            } else {
                break;
            }
        } else {
            break;
        }
    }

    let g1 = &section[..group1_len];
    let g2 = &section[group1_len..];
    (g1, g2)
}

fn rename_file(from: &Path, to: &Path) -> Result<(), std::io::Error> {
    std::fs::rename(from, to)
}

fn backup_file(path: &Path) -> Result<PathBuf, std::io::Error> {
    let backup_path = path.with_extension(
        path.extension()
            .map(|e| format!("{}.bk", e.to_string_lossy()))
            .unwrap_or_else(|| "bk".to_string()),
    );
    std::fs::copy(path, &backup_path)?;
    Ok(backup_path)
}

fn apply_transform(s: &str, transform: &Option<ReplaceTransform>) -> String {
    match transform {
        None => s.to_string(),
        Some(ReplaceTransform::Upper) => s.to_uppercase(),
        Some(ReplaceTransform::Lower) => s.to_lowercase(),
        Some(ReplaceTransform::Ascii) => unidecode::unidecode(s),
    }
}

fn compute_new_name(
    regex: &Regex,
    filename: &str,
    replacement: &str,
    limit: usize,
    transform: &Option<ReplaceTransform>,
) -> Option<String> {
    // Build replacement with transform applied
    let new_name = if limit == 0 {
        regex.replace_all(filename, |caps: &regex::Captures| {
            let replaced = caps.expand_str_to_string(replacement);
            apply_transform(&replaced, transform)
        }).to_string()
    } else {
        let mut count = 0;
        regex.replacen(filename, limit, |caps: &regex::Captures| {
            count += 1;
            let replaced = caps.expand_str_to_string(replacement);
            apply_transform(&replaced, transform)
        }).to_string()
    };

    if new_name != filename {
        Some(new_name)
    } else {
        None
    }
}

fn process_paths_regex(
    regex: &Regex,
    replacement: &str,
    paths: &[PathBuf],
    force: bool,
    backup: bool,
    silent: bool,
    use_color: bool,
    dump: bool,
    no_dump: bool,
    dump_prefix: &str,
    replace_limit: usize,
    replace_transform: &Option<ReplaceTransform>,
    include_dirs: bool,
    recursive: bool,
    max_depth: Option<usize>,
    hidden: bool,
) {
    let is_dry_run = !force;

    if !silent {
        if is_dry_run {
            if use_color {
                println!("{}", bold("This is a DRY-RUN"));
            } else {
                println!("This is a DRY-RUN");
            }
        }
    }

    let mut operations: Vec<Operation> = Vec::new();

    // Collect all paths to process
    let mut all_paths: Vec<PathBuf> = Vec::new();

    for path in paths {
        if recursive {
            let depth = max_depth.unwrap_or(usize::MAX);
            let walker = WalkDir::new(path)
                .max_depth(depth)
                .min_depth(1);

            for entry in walker {
                match entry {
                    Ok(e) => {
                        let ep = e.path().to_path_buf();
                        let is_hidden = ep.file_name()
                            .and_then(|n| n.to_str())
                            .map(|n| n.starts_with('.'))
                            .unwrap_or(false);
                        if !hidden && is_hidden {
                            continue;
                        }
                        if e.file_type().is_dir() {
                            if include_dirs {
                                all_paths.push(ep);
                            }
                        } else {
                            all_paths.push(ep);
                        }
                    }
                    Err(_) => {}
                }
            }
        } else {
            if path.is_dir() {
                if include_dirs {
                    all_paths.push(path.clone());
                }
            } else {
                all_paths.push(path.clone());
            }
        }
    }

    // Sort paths - process deeper paths first to avoid conflicts
    // Actually, let's process in the order they were found
    // but for dirs, we need to process deepest first

    for path in &all_paths {
        let filename = match path.file_name().and_then(|n| n.to_str()) {
            Some(f) => f,
            None => continue,
        };

        let new_filename = match compute_new_name(regex, filename, replacement, replace_limit, replace_transform) {
            Some(n) => n,
            None => continue,
        };

        let parent = path.parent().unwrap_or_else(|| Path::new(""));
        let new_path = parent.join(&new_filename);

        let op = Operation {
            source: path.to_string_lossy().to_string(),
            target: new_path.to_string_lossy().to_string(),
        };

        if !silent {
            if force {
                // backup first if requested
                if backup {
                    match backup_file(path) {
                        Ok(backup_path) => {
                            if use_color {
                                print!("{} ", bold("Info: "));
                                println!(" Backup created - {}", dark_gray(&format!("{} -> {}", path.display(), backup_path.display())));
                            } else {
                                println!("Info:  Backup created - {} -> {}", path.display(), backup_path.display());
                            }
                        }
                        Err(_) => {}
                    }
                }

                // Show the operation
                print_operation_color(path, &new_path, filename, &new_filename, regex, replacement, replace_limit, use_color);
            } else {
                // Dry run - just show
                print_operation_color(path, &new_path, filename, &new_filename, regex, replacement, replace_limit, use_color);
            }
        }

        if force {
            let _ = rename_file(path, &new_path);
        }

        operations.push(op);
    }

    // Handle dump
    let should_dump = if no_dump {
        false
    } else if dump {
        true
    } else {
        force // Only dump when actually making changes
    };

    if should_dump && !operations.is_empty() {
        write_dump(dump_prefix, &operations);
    }
}

fn print_operation_color(
    src_path: &Path,
    dst_path: &Path,
    src_filename: &str,
    dst_filename: &str,
    regex: &Regex,
    replacement: &str,
    limit: usize,
    use_color: bool,
) {
    if use_color {
        let src_parent = src_path.parent()
            .map(|p| format!("{}/", p.display()))
            .unwrap_or_default();
        let dst_parent = dst_path.parent()
            .map(|p| format!("{}/", p.display()))
            .unwrap_or_default();

        let colored_src = format!("{}{}", dark_gray(&src_parent), dark_gray(src_filename));
        let colored_dst_fn = colorize_filename_dest(regex, src_filename, replacement, limit);
        let colored_dst = format!("{}{}", green(&dst_parent), colored_dst_fn);

        println!("{} -> {}", colored_src, colored_dst);
    } else {
        println!("{} -> {}", src_path.display(), dst_path.display());
    }
}

fn write_dump(prefix: &str, operations: &[Operation]) {
    let now = Local::now();
    let filename = format!("{}{}", prefix, now.format("%Y-%m-%d_%H%M%S"));
    let dump = DumpFile {
        date: now.format("%Y-%m-%d %H:%M:%S").to_string(),
        operations: operations.iter().map(|op| Operation {
            source: op.source.clone(),
            target: op.target.clone(),
        }).collect(),
    };

    if let Ok(json) = serde_json::to_string_pretty(&dump) {
        let _ = std::fs::write(&filename, json);
    }
}

fn process_from_file(
    dumpfile: &Path,
    force: bool,
    backup: bool,
    silent: bool,
    use_color: bool,
    dump: bool,
    no_dump: bool,
    dump_prefix: &str,
    undo: bool,
) {
    let content = match std::fs::read_to_string(dumpfile) {
        Ok(c) => c,
        Err(e) => {
            eprintln!("Error: {}", e);
            return;
        }
    };

    let dump_data: DumpFile = match serde_json::from_str(&content) {
        Ok(d) => d,
        Err(e) => {
            eprintln!("Error: {}", e);
            return;
        }
    };

    let is_dry_run = !force;

    if !silent {
        if is_dry_run {
            if use_color {
                println!("{}", bold("This is a DRY-RUN"));
            } else {
                println!("This is a DRY-RUN");
            }
        }
    }

    let mut new_operations: Vec<Operation> = Vec::new();

    for op in &dump_data.operations {
        let (src, dst) = if undo {
            (&op.target, &op.source)
        } else {
            (&op.source, &op.target)
        };

        let src_path = Path::new(src);
        let dst_path = Path::new(dst);

        if !silent {
            if force {
                if backup {
                    if let Ok(backup_path) = backup_file(src_path) {
                        if use_color {
                            print!("{} ", bold("Info: "));
                            println!(" Backup created - {}", dark_gray(&format!("{} -> {}", src_path.display(), backup_path.display())));
                        } else {
                            println!("Info:  Backup created - {} -> {}", src_path.display(), backup_path.display());
                        }
                    }
                }
            }

            if use_color {
                let src_parent = src_path.parent()
                    .map(|p| format!("{}/", p.display()))
                    .unwrap_or_default();
                let dst_parent = dst_path.parent()
                    .map(|p| format!("{}/", p.display()))
                    .unwrap_or_default();
                let src_filename = src_path.file_name()
                    .and_then(|n| n.to_str())
                    .unwrap_or("");
                let dst_filename = dst_path.file_name()
                    .and_then(|n| n.to_str())
                    .unwrap_or("");

                println!("{}{} -> {}{}",
                    dark_gray(&src_parent), dark_gray(src_filename),
                    green(&dst_parent), green(dst_filename)
                );
            } else {
                println!("{} -> {}", src, dst);
            }
        }

        if force {
            let _ = rename_file(src_path, dst_path);
        }

        new_operations.push(Operation {
            source: src.clone(),
            target: dst.clone(),
        });
    }

    let should_dump = if no_dump { false } else if dump { true } else { force };
    if should_dump && !new_operations.is_empty() {
        write_dump(dump_prefix, &new_operations);
    }
}

fn to_ascii_filename(filename: &str) -> String {
    unidecode::unidecode(filename)
}

fn process_paths_to_ascii(
    paths: &[PathBuf],
    force: bool,
    backup: bool,
    silent: bool,
    use_color: bool,
    dump: bool,
    no_dump: bool,
    dump_prefix: &str,
    include_dirs: bool,
    recursive: bool,
    max_depth: Option<usize>,
    hidden: bool,
) {
    let is_dry_run = !force;

    if !silent {
        if is_dry_run {
            if use_color {
                println!("{}", bold("This is a DRY-RUN"));
            } else {
                println!("This is a DRY-RUN");
            }
        }
    }

    let mut operations: Vec<Operation> = Vec::new();
    let mut all_paths: Vec<PathBuf> = Vec::new();

    for path in paths {
        if recursive {
            let depth = max_depth.unwrap_or(usize::MAX);
            let walker = WalkDir::new(path)
                .max_depth(depth)
                .min_depth(1);

            for entry in walker {
                match entry {
                    Ok(e) => {
                        let ep = e.path().to_path_buf();
                        let is_hidden = ep.file_name()
                            .and_then(|n| n.to_str())
                            .map(|n| n.starts_with('.'))
                            .unwrap_or(false);
                        if !hidden && is_hidden {
                            continue;
                        }
                        if e.file_type().is_dir() {
                            if include_dirs {
                                all_paths.push(ep);
                            }
                        } else {
                            all_paths.push(ep);
                        }
                    }
                    Err(_) => {}
                }
            }
        } else {
            if path.is_dir() {
                if include_dirs {
                    all_paths.push(path.clone());
                }
            } else {
                all_paths.push(path.clone());
            }
        }
    }

    for path in &all_paths {
        let filename = match path.file_name().and_then(|n| n.to_str()) {
            Some(f) => f,
            None => continue,
        };

        let new_filename = to_ascii_filename(filename);
        if new_filename == filename {
            continue;
        }

        let parent = path.parent().unwrap_or_else(|| Path::new(""));
        let new_path = parent.join(&new_filename);

        if !silent {
            if use_color {
                let src_parent = path.parent()
                    .map(|p| format!("{}/", p.display()))
                    .unwrap_or_default();
                let dst_parent = new_path.parent()
                    .map(|p| format!("{}/", p.display()))
                    .unwrap_or_default();

                println!("{}{} -> {}{}",
                    dark_gray(&src_parent), dark_gray(filename),
                    green(&dst_parent), green(&new_filename)
                );
            } else {
                println!("{} -> {}", path.display(), new_path.display());
            }
        }

        if force {
            if backup {
                let _ = backup_file(path);
            }
            let _ = rename_file(path, &new_path);
        }

        operations.push(Operation {
            source: path.to_string_lossy().to_string(),
            target: new_path.to_string_lossy().to_string(),
        });
    }

    let should_dump = if no_dump { false } else if dump { true } else { force };
    if should_dump && !operations.is_empty() {
        write_dump(dump_prefix, &operations);
    }
}

// Helper trait for Captures
trait CapturesExt {
    fn expand_str_to_string(&self, replacement: &str) -> String;
}

impl<'t> CapturesExt for regex::Captures<'t> {
    fn expand_str_to_string(&self, replacement: &str) -> String {
        let mut dst = String::new();
        self.expand(replacement, &mut dst);
        dst
    }
}

fn main() {
    let cli = Cli::parse();

    match cli.command {
        Commands::Regex {
            expression,
            replacement,
            paths,
            dry_run: _,
            force,
            backup,
            silent,
            color,
            dump,
            dump_prefix,
            no_dump,
            replace_limit,
            replace_transform,
            include_dirs,
            recursive,
            max_depth,
            hidden,
        } => {
            let regex = match Regex::new(&expression) {
                Ok(r) => r,
                Err(e) => {
                    println!("Error: Bad expression provided\n\n{}", e);
                    std::process::exit(1);
                }
            };

            let use_col = use_color(&color);

            process_paths_regex(
                &regex,
                &replacement,
                &paths,
                force,
                backup,
                silent,
                use_col,
                dump,
                no_dump,
                &dump_prefix,
                replace_limit,
                &replace_transform,
                include_dirs,
                recursive,
                max_depth,
                hidden,
            );
        }
        Commands::FromFile {
            dumpfile,
            dry_run: _,
            force,
            backup,
            silent,
            color,
            dump,
            dump_prefix,
            no_dump,
            undo,
        } => {
            let use_col = use_color(&color);
            process_from_file(
                &dumpfile,
                force,
                backup,
                silent,
                use_col,
                dump,
                no_dump,
                &dump_prefix,
                undo,
            );
        }
        Commands::ToAscii {
            paths,
            dry_run: _,
            force,
            backup,
            silent,
            color,
            dump,
            dump_prefix,
            no_dump,
            include_dirs,
            recursive,
            max_depth,
            hidden,
        } => {
            let use_col = use_color(&color);
            process_paths_to_ascii(
                &paths,
                force,
                backup,
                silent,
                use_col,
                dump,
                no_dump,
                &dump_prefix,
                include_dirs,
                recursive,
                max_depth,
                hidden,
            );
        }
    }
}
