fn bold(s: &str) -> String {
    format!("\x1b[1m{}\x1b[0m", s)
}

fn green(s: &str) -> String {
    format!("\x1b[32m{}\x1b[0m", s)
}

fn bold_red(s: &str) -> String {
    format!("\x1b[1;31m{}\x1b[0m", s)
}

fn dark_gray(s: &str) -> String {
    format!("\x1b[38;5;8m{}\x1b[0m", s)
}

/// Compute common prefix length between two strings (in bytes)
fn common_prefix_len(a: &str, b: &str) -> usize {
    let a_bytes = a.as_bytes();
    let b_bytes = b.as_bytes();
    let mut n = 0;
    for i in 0..a_bytes.len().min(b_bytes.len()) {
        if a_bytes[i] == b_bytes[i] {
            n += 1;
        } else {
            break;
        }
    }
    n
}

/// Split a non-match section into two groups for coloring.
/// Group 1: longest prefix where each char's position in last_match_text
///           is strictly greater than the previous char's position.
/// Group 2: rest (one block)
fn split_two_groups<'a>(section: &'a str, last_match_text: &str) -> (&'a str, &'a str) {
    if last_match_text.is_empty() || section.is_empty() {
        return ("", section);
    }

    let match_chars: Vec<char> = last_match_text.chars().collect();
    let mut current_match_pos: Option<usize> = None;
    let mut group1_bytes = 0usize;

    for c in section.chars() {
        // Find position of c in match_chars that is > current_match_pos
        let found = match_chars.iter().enumerate().find(|(idx, &mc)| {
            mc == c && match current_match_pos {
                None => true,
                Some(cp) => *idx > cp,
            }
        });

        if let Some((pos, _)) = found {
            current_match_pos = Some(pos);
            group1_bytes += c.len_utf8();
        } else {
            break;
        }
    }

    (&section[..group1_bytes], &section[group1_bytes..])
}

/// Build colorized filename for destination
fn colorize_filename_dest(
    regex: &Regex,
    source: &str,
    replacement: &str,
    limit: usize,
) -> String {
    let mut output = String::new();
    let actual_limit = if limit == 0 { usize::MAX } else { limit };

    // Collect all matches
    let matches: Vec<regex::Match> = regex.find_iter(source).collect();
    let replaced_count = matches.len().min(actual_limit);

    // Build result string
    let result = if limit == 0 {
        regex.replace_all(source, replacement).to_string()
    } else {
        regex.replacen(source, limit, replacement).to_string()
    };

    let mut result_pos = 0usize;
    let mut source_pos = 0usize;
    let mut last_match_text = "";

    for (idx, m) in matches.iter().enumerate() {
        let is_replaced = idx < replaced_count;

        // Non-match section before this match
        let non_match = &source[source_pos..m.start()];
        if !non_match.is_empty() {
            let (g1, g2) = split_two_groups(non_match, last_match_text);
            if !g1.is_empty() {
                let result_slice = &result[result_pos..result_pos + g1.len()];
                output += &green(result_slice);
                result_pos += g1.len();
            }
            if !g2.is_empty() {
                let result_slice = &result[result_pos..result_pos + g2.len()];
                output += &green(result_slice);
                result_pos += g2.len();
            }
            source_pos = m.start();
        }

        if is_replaced {
            // Compute actual replacement length
            let actual_repl = {
                let mut dst = String::new();
                let caps = regex.captures(m.as_str()).unwrap();
                caps.expand(replacement, &mut dst);
                dst
            };

            // Find next non-match boundary in source
            let next_non_match_start = if idx + 1 < matches.len() {
                matches[idx + 1].start()
            } else {
                source.len()
            };
            let suffix_in_source = &source[m.end()..next_non_match_start];

            // Compute n = common prefix length between actual_repl and suffix_in_source
            let n = common_prefix_len(&actual_repl, suffix_in_source);

            // Green prefix (common prefix chars shown as green)
            if n > 0 {
                let green_slice = &result[result_pos..result_pos + n];
                output += &green(green_slice);
                result_pos += n;
            }

            // Red replacement
            if !actual_repl.is_empty() {
                let red_slice = &result[result_pos..result_pos + actual_repl.len()];
                output += &bold_red(red_slice);
                result_pos += actual_repl.len();
            }

            last_match_text = m.as_str();
            source_pos = m.end() + n;
        } else {
            // Non-replaced match: one green block
            let match_len = m.as_str().len();
            let match_result = &result[result_pos..result_pos + match_len];
            output += &green(match_result);
            result_pos += match_len;
            last_match_text = m.as_str();
            source_pos = m.end();
        }
    }

    // Remaining source after all matches
    let remaining = &source[source_pos..];
    if !remaining.is_empty() {
        let (g1, g2) = split_two_groups(remaining, last_match_text);
        if !g1.is_empty() {
            let result_slice = &result[result_pos..result_pos + g1.len()];
            output += &green(result_slice);
            result_pos += g1.len();
        }
        if !g2.is_empty() {
            let result_slice = &result[result_pos..result_pos + g2.len()];
            output += &green(result_slice);
        }
    }

    output
}

fn apply_transform(s: &str, transform: &Option<ReplaceTransform>) -> String {
    match transform {
        None => s.to_string(),
        Some(ReplaceTransform::Upper) => s.to_uppercase(),
        Some(ReplaceTransform::Lower) => s.to_lowercase(),
        Some(ReplaceTransform::Ascii) => unidecode::unidecode(s),
    }
}

fn compute_new_name(
    regex: &Regex,
    filename: &str,
    replacement: &str,
    limit: usize,
    transform: &Option<ReplaceTransform>,
) -> Option<String> {
    let new_name = if limit == 0 {
        regex.replace_all(filename, |caps: &regex::Captures| {
            let mut dst = String::new();
            caps.expand(replacement, &mut dst);
            apply_transform(&dst, transform)
        }).to_string()
    } else {
        regex.replacen(filename, limit, |caps: &regex::Captures| {
            let mut dst = String::new();
            caps.expand(replacement, &mut dst);
            apply_transform(&dst, transform)
        }).to_string()
    };

    if new_name != filename {
        Some(new_name)
    } else {
        None
    }
}

fn backup_file(path: &Path) -> Result<PathBuf, std::io::Error> {
    let ext = path.extension()
        .map(|e| format!("{}.bk", e.to_string_lossy()))
        .unwrap_or_else(|| "bk".to_string());
    let backup_path = path.with_extension(&ext);
    std::fs::copy(path, &backup_path)?;
    Ok(backup_path)
}

fn write_dump(prefix: &str, operations: &[Operation]) {
    let now = Local::now();
    let filename = format!("{}{}", prefix, now.format("%Y-%m-%d_%H%M%S"));
    let dump = DumpFile {
        date: now.format("%Y-%m-%d %H:%M:%S").to_string(),
        operations: operations.iter().map(|op| Operation {
            source: op.source.clone(),
            target: op.target.clone(),
        }).collect(),
    };

    if let Ok(json) = serde_json::to_string_pretty(&dump) {
        let _ = std::fs::write(&filename, json);
    }
}

fn collect_paths(
    paths: &[PathBuf],
    include_dirs: bool,
    recursive: bool,
    max_depth: Option<usize>,
    hidden: bool,
) -> Vec<PathBuf> {
    let mut all_paths: Vec<PathBuf> = Vec::new();

    for path in paths {
        if recursive {
            let depth = max_depth.unwrap_or(usize::MAX);
            let walker = WalkDir::new(path)
                .max_depth(depth)
                .min_depth(1);

            for entry in walker.into_iter() {
                match entry {
                    Ok(e) => {
                        let ep = e.path().to_path_buf();
                        let is_hidden_file = ep.file_name()
                            .and_then(|n| n.to_str())
                            .map(|n| n.starts_with('.'))
                            .unwrap_or(false);
                        if !hidden && is_hidden_file {
                            continue;
                        }
                        if e.file_type().is_dir() {
                            if include_dirs {
                                all_paths.push(ep);
                            }
                        } else {
                            all_paths.push(ep);
                        }
                    }
                    Err(_) => {}
                }
            }
        } else {
            if path.is_dir() {
                if include_dirs {
                    all_paths.push(path.clone());
                }
            } else {
                all_paths.push(path.clone());
            }
        }
    }

    all_paths
}

fn process_paths_regex(
    regex: &Regex,
    replacement: &str,
    paths: &[PathBuf],
    force: bool,
    backup: bool,
    silent: bool,
    colored: bool,
    dump: bool,
    no_dump: bool,
    dump_prefix: &str,
    replace_limit: usize,
    replace_transform: &Option<ReplaceTransform>,
    include_dirs: bool,
    recursive: bool,
    max_depth: Option<usize>,
    hidden: bool,
) {
    let is_dry_run = !force;

    if !silent {
        if is_dry_run {
            if colored {
                println!("{}", bold("This is a DRY-RUN"));
            } else {
                println!("This is a DRY-RUN");
            }
        }
    }

    let all_paths = collect_paths(paths, include_dirs, recursive, max_depth, hidden);
    let mut operations: Vec<Operation> = Vec::new();

    for path in &all_paths {
        let filename = match path.file_name().and_then(|n| n.to_str()) {
            Some(f) => f,
            None => continue,
        };

        let new_filename = match compute_new_name(regex, filename, replacement, replace_limit, replace_transform) {
            Some(n) => n,
            None => continue,
        };

        let parent = path.parent().unwrap_or_else(|| Path::new(""));
        let new_path = parent.join(&new_filename);

        if force && backup {
            match backup_file(path) {
                Ok(backup_path) => {
                    if !silent {
                        if colored {
                            print!("{} ", bold("Info: "));
                            print!(" Backup created - ");
                            println!("{}", dark_gray(&format!("{} -> {}", path.display(), backup_path.display())));
                        } else {
                            println!("Info:  Backup created - {} -> {}", path.display(), backup_path.display());
                        }
                    }
                }
                Err(_) => {}
            }
        }

        if !silent {
            if colored {
                let src_parent_str = path.parent()
                    .map(|p| {
                        let s = p.to_string_lossy();
                        if s.is_empty() { String::new() } else { format!("{}/", s) }
                    })
                    .unwrap_or_default();
                let dst_parent_str = new_path.parent()
                    .map(|p| {
                        let s = p.to_string_lossy();
                        if s.is_empty() { String::new() } else { format!("{}/", s) }
                    })
                    .unwrap_or_default();

                let colored_dest_fn = colorize_filename_dest(regex, filename, replacement, replace_limit);
                println!("{}{} -> {}{}",
                    dark_gray(&src_parent_str), dark_gray(filename),
                    green(&dst_parent_str), colored_dest_fn
                );
            } else {
                println!("{} -> {}", path.display(), new_path.display());
            }
        }

        if force {
            let _ = std::fs::rename(path, &new_path);
        }

        operations.push(Operation {
            source: path.to_string_lossy().to_string(),
            target: new_path.to_string_lossy().to_string(),
        });
    }

    let should_dump = if no_dump {
        false
    } else if dump {
        true
    } else {
        force
    };

    if should_dump && !operations.is_empty() {
        write_dump(dump_prefix, &operations);
    }
}

fn process_from_file(
    dumpfile: &Path,
    force: bool,
    backup: bool,
    silent: bool,
    colored: bool,
    dump: bool,
    no_dump: bool,
    dump_prefix: &str,
    undo: bool,
) {
    let content = match std::fs::read_to_string(dumpfile) {
        Ok(c) => c,
        Err(e) => {
            eprintln!("Error: {}", e);
            return;
        }
    };

    let dump_data: DumpFile = match serde_json::from_str(&content) {
        Ok(d) => d,
        Err(e) => {
            eprintln!("Error: {}", e);
            return;
        }
    };

    let is_dry_run = !force;

    if !silent {
        if is_dry_run {
            if colored {
                println!("{}", bold("This is a DRY-RUN"));
            } else {
                println!("This is a DRY-RUN");
            }
        }
    }

    let mut new_operations: Vec<Operation> = Vec::new();

    for op in &dump_data.operations {
        let (src, dst) = if undo {
            (op.target.as_str(), op.source.as_str())
        } else {
            (op.source.as_str(), op.target.as_str())
        };

        let src_path = Path::new(src);
        let dst_path = Path::new(dst);

        if force && backup {
            if let Ok(backup_path) = backup_file(src_path) {
                if !silent {
                    if colored {
                        print!("{} ", bold("Info: "));
                        print!(" Backup created - ");
                        println!("{}", dark_gray(&format!("{} -> {}", src_path.display(), backup_path.display())));
                    } else {
                        println!("Info:  Backup created - {} -> {}", src_path.display(), backup_path.display());
                    }
                }
            }
        }

        if !silent {
            if colored {
                let src_parent_str = src_path.parent()
                    .map(|p| {
                        let s = p.to_string_lossy();
                        if s.is_empty() { String::new() } else { format!("{}/", s) }
                    })
                    .unwrap_or_default();
                let dst_parent_str = dst_path.parent()
                    .map(|p| {
                        let s = p.to_string_lossy();
                        if s.is_empty() { String::new() } else { format!("{}/", s) }
                    })
                    .unwrap_or_default();
                let src_filename = src_path.file_name()
                    .and_then(|n| n.to_str())
                    .unwrap_or("");
                let dst_filename = dst_path.file_name()
                    .and_then(|n| n.to_str())
                    .unwrap_or("");

                println!("{}{} -> {}{}",
                    dark_gray(&src_parent_str), dark_gray(src_filename),
                    green(&dst_parent_str), green(dst_filename)
                );
            } else {
                println!("{} -> {}", src, dst);
            }
        }

        if force {
            let _ = std::fs::rename(src_path, dst_path);
        }

        new_operations.push(Operation {
            source: src.to_string(),
            target: dst.to_string(),
        });
    }

    let should_dump = if no_dump { false } else if dump { true } else { force };
    if should_dump && !new_operations.is_empty() {
        write_dump(dump_prefix, &new_operations);
    }
}

