        #[arg(long = "no-dump", help = "Do not dump operations into a file", conflicts_with = "dump")]
        no_dump: bool,
        #[arg(short = 'D', long = "include-dirs", help = "Rename matching directories")]
        include_dirs: bool,
        #[arg(short = 'r', long = "recursive", help = "Recursive mode")]
        recursive: bool,
        #[arg(short = 'd', long = "max-depth", name = "LEVEL", help = "Set max depth in recursive mode")]
        max_depth: Option<usize>,
        #[arg(short = 'x', long = "hidden", help = "Include hidden files and directories")]
