package main

import (
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"regexp"
	"strings"
	"time"
	"unicode"
	"unicode/utf8"
)

const version = "0.5.1"

// ANSI color codes
func bold(s string) string       { return "\x1b[1m" + s + "\x1b[0m" }
func green(s string) string      { return "\x1b[32m" + s + "\x1b[0m" }
func boldRed(s string) string    { return "\x1b[1;31m" + s + "\x1b[0m" }
func darkGray(s string) string   { return "\x1b[38;5;8m" + s + "\x1b[0m" }

type Operation struct {
	Source string `json:"source"`
	Target string `json:"target"`
}

type DumpFile struct {
	Date       string      `json:"date"`
	Operations []Operation `json:"operations"`
}

func writeDump(prefix string, ops []Operation) {
	now := time.Now()
	filename := prefix + now.Format("2006-01-02_150405")
	data := DumpFile{
		Date:       now.Format("2006-01-02 15:04:05"),
		Operations: ops,
	}
	b, err := json.MarshalIndent(data, "", "  ")
	if err == nil {
		_ = os.WriteFile(filename, b, 0644)
	}
}

func isHidden(name string) bool {
	return strings.HasPrefix(name, ".")
}

func backupFile(path string) (string, error) {
	ext := filepath.Ext(path)
	var backupPath string
	if ext != "" {
		backupPath = path[:len(path)-len(ext)] + ext + ".bk"
	} else {
		backupPath = path + ".bk"
	}

	data, err := os.ReadFile(path)
	if err != nil {
		// Try as directory - just note we can't copy dirs easily
		return backupPath, err
	}
	err = os.WriteFile(backupPath, data, 0644)
	if err != nil {
		return backupPath, err
	}
	return backupPath, nil
}

func applyTransform(s string, transform string) string {
	switch transform {
	case "upper":
		return strings.ToUpper(s)
	case "lower":
		return strings.ToLower(s)
	case "ascii":
		return toAscii(s)
	}
	return s
}

// replaceN applies regex replacement with a limit (0 = all)
func replaceN(re *regexp.Regexp, src, repl string, limit int) string {
	if limit == 0 {
		return re.ReplaceAllString(src, repl)
	}
	count := 0
	return re.ReplaceAllStringFunc(src, func(match string) string {
		if count < limit {
			count++
			return re.ReplaceAllString(match, repl)
		}
		return match
	})
}

// replaceNWithTransform applies regex replacement with limit and transform
func replaceNWithTransform(re *regexp.Regexp, src, repl string, limit int, transform string) string {
	if transform == "" {
		return replaceN(re, src, repl, limit)
	}

	if limit == 0 {
		return re.ReplaceAllStringFunc(src, func(match string) string {
			expanded := re.ReplaceAllString(match, repl)
			return applyTransform(expanded, transform)
		})
	}

	count := 0
	return re.ReplaceAllStringFunc(src, func(match string) string {
		if count < limit {
			count++
			expanded := re.ReplaceAllString(match, repl)
			return applyTransform(expanded, transform)
		}
		return match
	})
}

func computeNewName(re *regexp.Regexp, filename, replacement string, limit int, transform string) (string, bool) {
	newName := replaceNWithTransform(re, filename, replacement, limit, transform)
	if newName != filename {
		return newName, true
	}
	return "", false
}

// commonPrefixLen returns the byte length of the common prefix of two strings
func commonPrefixLen(a, b string) int {
	n := 0
	for n < len(a) && n < len(b) && a[n] == b[n] {
		n++
	}
	return n
}

// splitTwoGroups splits a non-match section into two groups:
// Group1: longest prefix where each char's position in lastMatch is strictly increasing
// Group2: the rest
func splitTwoGroups(section, lastMatch string) (string, string) {
	if lastMatch == "" || section == "" {
		return "", section
	}

	matchRunes := []rune(lastMatch)
	sectionRunes := []rune(section)

	currentMatchPos := -1
	group1Len := 0

	for _, c := range sectionRunes {
		foundPos := -1
		for i, mc := range matchRunes {
			if mc == c && i > currentMatchPos {
				foundPos = i
				break
			}
		}
		if foundPos == -1 {
			break
		}
		currentMatchPos = foundPos
		group1Len += utf8.RuneLen(c)
	}

	return section[:group1Len], section[group1Len:]
}

// colorizeFilenameDest builds colorized filename for destination
func colorizeFilenameDest(re *regexp.Regexp, source, replacement string, limit int) string {
	actualLimit := limit
	if limit == 0 {
		actualLimit = 1<<62
	}

	// Compute full result string
	result := replaceN(re, source, replacement, limit)

	// Find all matches in source
	matches := re.FindAllStringIndex(source, -1)
	matchStrings := re.FindAllString(source, -1)

	if len(matches) == 0 {
		// No match - return as green
		return green(result)
	}

	replacedCount := len(matches)
	if actualLimit < replacedCount {
		replacedCount = actualLimit
	}

	var output strings.Builder
	resultPos := 0
	sourcePos := 0
	lastMatchText := ""

	for idx, m := range matches {
		isReplaced := idx < replacedCount
		matchStart := m[0]
		matchEnd := m[1]
		matchText := matchStrings[idx]

		// Non-match section before this match
		nonMatch := source[sourcePos:matchStart]
		if len(nonMatch) > 0 {
			g1, g2 := splitTwoGroups(nonMatch, lastMatchText)
			if len(g1) > 0 {
				resultSlice := result[resultPos : resultPos+len(g1)]
				output.WriteString(green(resultSlice))
				resultPos += len(g1)
			}
			if len(g2) > 0 {
				resultSlice := result[resultPos : resultPos+len(g2)]
				output.WriteString(green(resultSlice))
				resultPos += len(g2)
			}
			sourcePos = matchStart
		}

		if isReplaced {
			// Compute the actual replacement for this match
			actualRepl := re.ReplaceAllString(matchText, replacement)

			// Find suffix in source after this match
			nextNonMatchStart := len(source)
			if idx+1 < len(matches) {
				nextNonMatchStart = matches[idx+1][0]
			}
			suffixInSource := source[matchEnd:nextNonMatchStart]

			// Compute n = common prefix length
			n := commonPrefixLen(actualRepl, suffixInSource)

			// Green prefix
			if n > 0 {
				greenSlice := result[resultPos : resultPos+n]
				output.WriteString(green(greenSlice))
				resultPos += n
			}

			// Red replacement
			if len(actualRepl) > 0 {
				redSlice := result[resultPos : resultPos+len(actualRepl)]
				output.WriteString(boldRed(redSlice))
				resultPos += len(actualRepl)
			}

			lastMatchText = matchText
			sourcePos = matchEnd + n
		} else {
			// Non-replaced match: one green block
			matchLen := len(matchText)
			matchResult := result[resultPos : resultPos+matchLen]
			output.WriteString(green(matchResult))
			resultPos += matchLen
			lastMatchText = matchText
			sourcePos = matchEnd
		}
	}

	// Remaining source
	remaining := source[sourcePos:]
	if len(remaining) > 0 {
		g1, g2 := splitTwoGroups(remaining, lastMatchText)
		if len(g1) > 0 {
			resultSlice := result[resultPos : resultPos+len(g1)]
			output.WriteString(green(resultSlice))
			resultPos += len(g1)
		}
		if len(g2) > 0 {
			resultSlice := result[resultPos : resultPos+len(g2)]
			output.WriteString(green(resultSlice))
			resultPos += len(g2)
		}
	}
	_ = resultPos

	return output.String()
}

func isTerminal(f *os.File) bool {
	fileInfo, err := f.Stat()
	if err != nil {
		return false
	}
	return (fileInfo.Mode() & os.ModeCharDevice) != 0
}

func useColor(colorMode string) bool {
	switch colorMode {
	case "always":
		return true
	case "never":
		return false
	default: // auto
		return isTerminal(os.Stdout)
	}
}

type Config struct {
	Force         bool
	Backup        bool
	Silent        bool
	Colored       bool
	Dump          bool
	NoDump        bool
	DumpPrefix    string
	IncludeDirs   bool
	Recursive     bool
	MaxDepth      int
	Hidden        bool
