func parseError(msg string) {
	fmt.Fprintf(os.Stderr, "error: %s\n\nUsage: rnr <COMMAND>\n\nFor more information, try '--help'.\n", msg)
	os.Exit(2)
}

func parseArgs(args []string) Args {
	result := Args{
		ColorMode:    "auto",
		DumpPrefix:   "rnr-",
		ReplaceLimit: 1,
	}

	if len(args) == 0 {
		parseError("no subcommand provided")
	}

	// Check for top-level flags
	firstArg := args[0]
	if firstArg == "--help" || firstArg == "-h" {
		printHelp()
		os.Exit(0)
	}
	if firstArg == "--version" || firstArg == "-V" {
		fmt.Printf("rnr %s\n", version)
		os.Exit(0)
	}

	result.Subcommand = args[0]
	remaining := args[1:]

	switch result.Subcommand {
	case "regex":
		result = parseRegexArgs(result, remaining)
	case "from-file":
		result = parseFromFileArgs(result, remaining)
	case "to-ascii":
		result = parseToAsciiArgs(result, remaining)
	case "help":
		if len(remaining) > 0 {
			switch remaining[0] {
			case "regex":
				printRegexHelp()
			case "from-file":
				printFromFileHelp()
			case "to-ascii":
				printToAsciiHelp()
			default:
				printHelp()
			}
		} else {
			printHelp()
		}
		os.Exit(0)
	default:
		parseError(fmt.Sprintf("unrecognized subcommand '%s'", result.Subcommand))
	}

	return result
}

func parseCommonFlags(args []string, res *Args, remainingAfterFlags *[]string) {
	i := 0
	for i < len(args) {
		arg := args[i]
		switch arg {
		case "-n", "--dry-run":
			// dry-run is default, so just ignore
		case "-f", "--force":
			res.Force = true
		case "-b", "--backup":
			res.Backup = true
		case "-s", "--silent":
			res.Silent = true
		case "--color":
			i++
			if i < len(args) {
				res.ColorMode = args[i]
			}
		case "--dump":
			if res.NoDump {
				fmt.Fprintf(os.Stderr, "error: the argument '--dump' cannot be used with '--no-dump'\n\nUsage: rnr regex --dump <EXPRESSION> <REPLACEMENT> <PATH(S)>...\n\nFor more information, try '--help'.\n")
				os.Exit(2)
			}
			res.Dump = true
		case "--no-dump":
			if res.Dump {
				fmt.Fprintf(os.Stderr, "error: the argument '--dump' cannot be used with '--no-dump'\n\nUsage: rnr regex --dump <EXPRESSION> <REPLACEMENT> <PATH(S)>...\n\nFor more information, try '--help'.\n")
				os.Exit(2)
			}
			res.NoDump = true
		case "--dump-prefix":
			i++
			if i < len(args) {
				res.DumpPrefix = args[i]
			}
		case "-h", "--help":
			switch res.Subcommand {
			case "regex":
				printRegexHelp()
			case "from-file":
				printFromFileHelp()
			case "to-ascii":
				printToAsciiHelp()
			}
			os.Exit(0)
		default:
			// Check for --color=value format
			if strings.HasPrefix(arg, "--color=") {
				res.ColorMode = arg[8:]
			} else if strings.HasPrefix(arg, "--dump-prefix=") {
				res.DumpPrefix = arg[14:]
			} else {
				*remainingAfterFlags = append(*remainingAfterFlags, arg)
			}
		}
		i++
	}
}

func parseRegexArgs(res Args, args []string) Args {
	var positional []string

	i := 0
	for i < len(args) {
		arg := args[i]
		switch arg {
		case "-n", "--dry-run":
		case "-f", "--force":
			res.Force = true
		case "-b", "--backup":
			res.Backup = true
		case "-s", "--silent":
			res.Silent = true
		case "--color":
			i++
			if i < len(args) { res.ColorMode = args[i] }
		case "--dump":
			if res.NoDump {
				fmt.Fprintf(os.Stderr, "error: the argument '--dump' cannot be used with '--no-dump'\n\nUsage: rnr regex --dump <EXPRESSION> <REPLACEMENT> <PATH(S)>...\n\nFor more information, try '--help'.\n")
				os.Exit(2)
			}
			res.Dump = true
		case "--no-dump":
			if res.Dump {
				fmt.Fprintf(os.Stderr, "error: the argument '--dump' cannot be used with '--no-dump'\n\nUsage: rnr regex --dump <EXPRESSION> <REPLACEMENT> <PATH(S)>...\n\nFor more information, try '--help'.\n")
				os.Exit(2)
			}
			res.NoDump = true
		case "--dump-prefix":
			i++
			if i < len(args) { res.DumpPrefix = args[i] }
		case "-l", "--replace-limit":
			i++
			if i < len(args) {
				fmt.Sscanf(args[i], "%d", &res.ReplaceLimit)
			}
		case "-t", "--replace-transform":
			i++
			if i < len(args) { res.Transform = args[i] }
		case "-D", "--include-dirs":
			res.IncludeDirs = true
		case "-r", "--recursive":
			res.Recursive = true
		case "-d", "--max-depth":
			i++
			if i < len(args) {
				fmt.Sscanf(args[i], "%d", &res.MaxDepth)
			}
		case "-x", "--hidden":
			res.Hidden = true
		case "-h", "--help":
			printRegexHelp()
			os.Exit(0)
		default:
			if strings.HasPrefix(arg, "--color=") {
				res.ColorMode = arg[8:]
			} else if strings.HasPrefix(arg, "--dump-prefix=") {
				res.DumpPrefix = arg[14:]
			} else if strings.HasPrefix(arg, "-l") && len(arg) > 2 {
				fmt.Sscanf(arg[2:], "%d", &res.ReplaceLimit)
			} else if strings.HasPrefix(arg, "--replace-limit=") {
				fmt.Sscanf(arg[16:], "%d", &res.ReplaceLimit)
			} else if strings.HasPrefix(arg, "-t") && len(arg) > 2 {
				res.Transform = arg[2:]
			} else if strings.HasPrefix(arg, "--replace-transform=") {
				res.Transform = arg[20:]
			} else if strings.HasPrefix(arg, "-d") && len(arg) > 2 {
				fmt.Sscanf(arg[2:], "%d", &res.MaxDepth)
			} else if strings.HasPrefix(arg, "--max-depth=") {
				fmt.Sscanf(arg[12:], "%d", &res.MaxDepth)
			} else {
				positional = append(positional, arg)
			}
		}
		i++
	}

	if len(positional) < 2 {
		parseError("missing required arguments: <EXPRESSION> <REPLACEMENT>")
	}

	res.Expression = positional[0]
	res.Replacement = positional[1]
	res.Paths = positional[2:]

	if len(res.Paths) == 0 {
		parseError("missing required argument: <PATH(S)>")
	}

	return res
}

