// toAscii transliterates a string to ASCII using unidecode-like tables
func toAscii(s string) string {
	var result strings.Builder
	for _, r := range s {
		if r < 128 {
			result.WriteRune(r)
			continue
		}
		ascii := unicodeToAscii(r)
		result.WriteString(ascii)
	}
	return result.String()
}

// unicodeToAscii converts a Unicode rune to its ASCII representation
// This is based on the unidecode algorithm with common character tables
func unicodeToAscii(r rune) string {
	// Try Unicode normalization first for combining characters
	block := r / 256
	_ = block

	// Use the transliteration table
	if str, ok := transliterationTable[r]; ok {
		return str
	}

	// For characters we don't have, try NFKD decomposition
	// using a simple lookup for common combining marks
	normalized := normalizeToAscii(r)
	if normalized != "" {
		return normalized
	}

	return ""
}

// normalizeToAscii tries to convert a Unicode character to ASCII
// by stripping combining marks
func normalizeToAscii(r rune) string {
	// Simple decomposition table for common European characters
	decomp := map[rune]string{
		'À': "A", 'Á': "A", 'Â': "A", 'Ã': "A", 'Ä': "A", 'Å': "A",
		'à': "a", 'á': "a", 'â': "a", 'ã': "a", 'ä': "a", 'å': "a",
		'Æ': "AE", 'æ': "ae",
		'Ç': "C", 'ç': "c",
		'È': "E", 'É': "E", 'Ê': "E", 'Ë': "E",
		'è': "e", 'é': "e", 'ê': "e", 'ë': "e",
		'Ì': "I", 'Í': "I", 'Î': "I", 'Ï': "I",
		'ì': "i", 'í': "i", 'î': "i", 'ï': "i",
		'Ð': "D", 'ð': "d",
		'Ñ': "N", 'ñ': "n",
		'Ò': "O", 'Ó': "O", 'Ô': "O", 'Õ': "O", 'Ö': "O", 'Ø': "O",
		'ò': "o", 'ó': "o", 'ô': "o", 'õ': "o", 'ö': "o", 'ø': "o",
		'Ù': "U", 'Ú': "U", 'Û': "U", 'Ü': "U",
		'ù': "u", 'ú': "u", 'û': "u", 'ü': "u",
		'Ý': "Y", 'ý': "y", 'ÿ': "y",
		'Þ': "Th", 'þ': "th",
		'ß': "ss",
		// More characters
		'Š': "S", 'š': "s", 'Ž': "Z", 'ž': "z",
		'Ā': "A", 'ā': "a", 'Ă': "A", 'ă': "a", 'Ą': "A", 'ą': "a",
