type Args struct {
	Subcommand   string
	Expression   string
	Replacement  string
	Paths        []string
	Force        bool
	Backup       bool
	Silent       bool
	ColorMode    string
	Dump         bool
	NoDump       bool
	DumpPrefix   string
	ReplaceLimit int
	Transform    string
	IncludeDirs  bool
	Recursive    bool
	MaxDepth     int
	Hidden       bool
	DumpFile     string
	Undo         bool
}

func parseRegexArgs(res Args, args []string) Args {
	var positional []string

	i := 0
	for i < len(args) {
		arg := args[i]
		switch arg {
		case "-n", "--dry-run":
		case "-f", "--force":
			res.Force = true
		case "-b", "--backup":
			res.Backup = true
		case "-s", "--silent":
			res.Silent = true
		case "--color":
			i++
			if i < len(args) {
				res.ColorMode = args[i]
			}
		case "--dump":
			if res.NoDump {
				fmt.Fprintf(os.Stderr, "error: the argument '--dump' cannot be used with '--no-dump'\n\nUsage: rnr regex --dump <EXPRESSION> <REPLACEMENT> <PATH(S)>...\n\nFor more information, try '--help'.\n")
				os.Exit(2)
			}
			res.Dump = true
		case "--no-dump":
			if res.Dump {
				fmt.Fprintf(os.Stderr, "error: the argument '--dump' cannot be used with '--no-dump'\n\nUsage: rnr regex --dump <EXPRESSION> <REPLACEMENT> <PATH(S)>...\n\nFor more information, try '--help'.\n")
				os.Exit(2)
			}
			res.NoDump = true
		case "--dump-prefix":
			i++
			if i < len(args) {
				res.DumpPrefix = args[i]
			}
		case "-l", "--replace-limit":
			i++
			if i < len(args) {
				fmt.Sscanf(args[i], "%d", &res.ReplaceLimit)
			}
		case "-t", "--replace-transform":
			i++
			if i < len(args) {
				res.Transform = args[i]
			}
		case "-D", "--include-dirs":
			res.IncludeDirs = true
		case "-r", "--recursive":
			res.Recursive = true
		case "-d", "--max-depth":
			i++
			if i < len(args) {
