				res.ColorMode = arg[8:]
			} else if strings.HasPrefix(arg, "--dump-prefix=") {
				res.DumpPrefix = arg[14:]
			} else if strings.HasPrefix(arg, "--replace-limit=") {
				fmt.Sscanf(arg[16:], "%d", &res.ReplaceLimit)
			} else if strings.HasPrefix(arg, "--replace-transform=") {
				res.Transform = arg[20:]
			} else if strings.HasPrefix(arg, "--max-depth=") {
				fmt.Sscanf(arg[12:], "%d", &res.MaxDepth)
			} else if len(arg) > 2 && arg[0] == '-' && arg[1] != '-' {
				// Handle combined short flags like -l1
				flag := arg[1:2]
				value := arg[2:]
				switch flag {
				case "l":
					fmt.Sscanf(value, "%d", &res.ReplaceLimit)
				case "t":
					res.Transform = value
				case "d":
					fmt.Sscanf(value, "%d", &res.MaxDepth)
				default:
					positional = append(positional, arg)
				}
			} else {
				positional = append(positional, arg)
			}
		}
		i++
	}

