		_ = os.WriteFile(filename, b, 0644)
	}
}

func isHidden(name string) bool {
	return strings.HasPrefix(name, ".")
}

func backupFile(path string) (string, error) {
	ext := filepath.Ext(path)
	var backupPath string
	if ext != "" {
		backupPath = path[:len(path)-len(ext)] + ext + ".bk"
	} else {
		backupPath = path + ".bk"
	}

	info, err := os.Stat(path)
	if err != nil {
		return backupPath, err
	}

	if info.IsDir() {
		// Can't easily copy a directory, just skip
		return backupPath, fmt.Errorf("cannot backup directory")
	}

	data, err := os.ReadFile(path)
	if err != nil {
		return backupPath, err
	}
	err = os.WriteFile(backupPath, data, info.Mode())
	return backupPath, err
}

func applyTransform(s string, transform string) string {
	switch transform {
	case "upper":
		return strings.ToUpper(s)
	case "lower":
		return strings.ToLower(s)
	case "ascii":
		return toAscii(s)
	}
	return s
}

// replaceN applies regex replacement with a limit (0 = all)
func replaceN(re *regexp.Regexp, src, repl string, limit int) string {
	if limit == 0 {
		return re.ReplaceAllString(src, repl)
	}
	count := 0
	return re.ReplaceAllStringFunc(src, func(match string) string {
		if count < limit {
			count++
			return re.ReplaceAllString(match, repl)
		}
		return match
	})
}

// replaceNWithTransform applies regex replacement with limit and transform
func replaceNWithTransform(re *regexp.Regexp, src, repl string, limit int, transform string) string {
	if transform == "" {
		return replaceN(re, src, repl, limit)
	}

	if limit == 0 {
		return re.ReplaceAllStringFunc(src, func(match string) string {
			expanded := re.ReplaceAllString(match, repl)
			return applyTransform(expanded, transform)
		})
	}

	count := 0
	return re.ReplaceAllStringFunc(src, func(match string) string {
		if count < limit {
			count++
			expanded := re.ReplaceAllString(match, repl)
			return applyTransform(expanded, transform)
		}
		return match
	})
}

func computeNewName(re *regexp.Regexp, filename, replacement string, limit int, transform string) (string, bool) {
	newName := replaceNWithTransform(re, filename, replacement, limit, transform)
	if newName != filename {
		return newName, true
	}
	return "", false
}

// commonPrefixLen returns the byte length of the common prefix of two strings
func commonPrefixLen(a, b string) int {
	n := 0
	for n < len(a) && n < len(b) && a[n] == b[n] {
		n++
	}
	return n
}

// splitTwoGroups splits a non-match section into two groups:
// Group1: longest prefix where each rune's position in lastMatch is strictly increasing
// Group2: the rest
func splitTwoGroups(section, lastMatch string) (string, string) {
	if lastMatch == "" || section == "" {
		return "", section
	}

	matchRunes := []rune(lastMatch)
	currentMatchPos := -1
	group1Bytes := 0

	for _, c := range section {
		foundPos := -1
		for i, mc := range matchRunes {
			if mc == c && i > currentMatchPos {
				foundPos = i
				break
			}
		}
		if foundPos == -1 {
			break
		}
		currentMatchPos = foundPos
		group1Bytes += utf8.RuneLen(c)
	}

	return section[:group1Bytes], section[group1Bytes:]
}

// colorizeFilenameDest builds colorized filename for destination
func colorizeFilenameDest(re *regexp.Regexp, source, replacement string, limit int) string {
	actualLimit := limit
	if limit == 0 {
		actualLimit = 1 << 30
	}

	// Compute full result string
	result := replaceN(re, source, replacement, limit)

	// Find all matches in source
	matches := re.FindAllStringIndex(source, -1)
	matchStrings := re.FindAllString(source, -1)

	if len(matches) == 0 {
		return green(result)
	}

	replacedCount := len(matches)
	if actualLimit < replacedCount {
		replacedCount = actualLimit
	}

	var output strings.Builder
	resultPos := 0
	sourcePos := 0
	lastMatchText := ""

	for idx, m := range matches {
		isReplaced := idx < replacedCount
		matchStart := m[0]
		matchEnd := m[1]
		matchText := matchStrings[idx]

		// Non-match section before this match
		nonMatch := source[sourcePos:matchStart]
		if len(nonMatch) > 0 {
			g1, g2 := splitTwoGroups(nonMatch, lastMatchText)
			if len(g1) > 0 {
				resultSlice := result[resultPos : resultPos+len(g1)]
				output.WriteString(green(resultSlice))
				resultPos += len(g1)
			}
			if len(g2) > 0 {
				resultSlice := result[resultPos : resultPos+len(g2)]
				output.WriteString(green(resultSlice))
				resultPos += len(g2)
			}
			sourcePos = matchStart
		}

		if isReplaced {
			// Compute the actual replacement for this match
			actualRepl := re.ReplaceAllString(matchText, replacement)

			// Find suffix in source after this match
			nextNonMatchStart := len(source)
			if idx+1 < len(matches) {
				nextNonMatchStart = matches[idx+1][0]
			}
			suffixInSource := source[matchEnd:nextNonMatchStart]

			// Compute n = common prefix length
			n := commonPrefixLen(actualRepl, suffixInSource)

			// Green prefix (common prefix chars)
			if n > 0 {
				greenSlice := result[resultPos : resultPos+n]
				output.WriteString(green(greenSlice))
				resultPos += n
			}

			// Red replacement
			if len(actualRepl) > 0 {
				redSlice := result[resultPos : resultPos+len(actualRepl)]
				output.WriteString(boldRed(redSlice))
				resultPos += len(actualRepl)
			}

			lastMatchText = matchText
			sourcePos = matchEnd + n
		} else {
			// Non-replaced match: one green block
			matchLen := len(matchText)
			matchResult := result[resultPos : resultPos+matchLen]
			output.WriteString(green(matchResult))
			resultPos += matchLen
			lastMatchText = matchText
			sourcePos = matchEnd
		}
	}

	// Remaining source
	remaining := source[sourcePos:]
	if len(remaining) > 0 {
		g1, g2 := splitTwoGroups(remaining, lastMatchText)
		if len(g1) > 0 {
			resultSlice := result[resultPos : resultPos+len(g1)]
			output.WriteString(green(resultSlice))
			resultPos += len(g1)
		}
		if len(g2) > 0 {
			if resultPos < len(result) {
				resultSlice := result[resultPos : resultPos+len(g2)]
				output.WriteString(green(resultSlice))
			}
		}
	}

	return output.String()
}

func isTerminal(f *os.File) bool {
	fileInfo, err := f.Stat()
	if err != nil {
		return false
	}
	return (fileInfo.Mode() & os.ModeCharDevice) != 0
}

func useColor(colorMode string) bool {
	switch colorMode {
	case "always":
		return true
	case "never":
		return false
	default: // auto
		return isTerminal(os.Stdout)
	}
}

type Config struct {
	Force        bool
	Backup       bool
	Silent       bool
	Colored      bool
	Dump         bool
	NoDump       bool
	DumpPrefix   string
	IncludeDirs  bool
	Recursive    bool
	MaxDepth     int
	Hidden       bool
	ReplaceLimit int
	Transform    string
	Undo         bool
}

func printDryRunHeader(colored bool) {
	if colored {
		fmt.Println(bold("This is a DRY-RUN"))
	} else {
		fmt.Println("This is a DRY-RUN")
	}
}

func printBackupInfo(src, backup string, colored bool) {
	if colored {
		fmt.Print(bold("Info: ") + " Backup created - ")
		fmt.Println(darkGray(src + " -> " + backup))
	} else {
		fmt.Printf("Info:  Backup created - %s -> %s\n", src, backup)
	}
}

func collectPaths(paths []string, cfg Config) []string {
	var allPaths []string

	for _, p := range paths {
		info, err := os.Stat(p)
		if err != nil {
			continue
		}

		if cfg.Recursive {
			depth := cfg.MaxDepth
			if depth == 0 {
				depth = 1 << 30
			}
			walkDir(p, 0, depth, cfg.IncludeDirs, cfg.Hidden, &allPaths)
		} else {
			if info.IsDir() {
				if cfg.IncludeDirs {
					allPaths = append(allPaths, p)
				}
			} else {
				allPaths = append(allPaths, p)
			}
		}
	}

	// Sort paths alphabetically
	sort.Strings(allPaths)

	return allPaths
}

func walkDir(dir string, currentDepth, maxDepth int, includeDirs, hidden bool, result *[]string) {
	if currentDepth >= maxDepth {
		return
	}

	entries, err := os.ReadDir(dir)
	if err != nil {
		return
	}

	// Sort entries for deterministic order
	for _, entry := range entries {
		name := entry.Name()
		if !hidden && isHidden(name) {
			continue
		}

		fullPath := filepath.Join(dir, name)

		if entry.IsDir() {
			if includeDirs {
				*result = append(*result, fullPath)
			}
			walkDir(fullPath, currentDepth+1, maxDepth, includeDirs, hidden, result)
		} else {
			*result = append(*result, fullPath)
		}
	}
}

func pathParent(path string) string {
	dir := filepath.Dir(path)
	if dir == "." {
		return ""
	}
	return dir + "/"
}

// checkConflicts checks for duplicate targets and existing file conflicts.
// Returns error message if conflict found.
type RenameOp struct {
	Source string
	Target string
}

func checkConflicts(ops []RenameOp) (string, []RenameOp) {
	// Check for duplicate targets
	targetMap := make(map[string][]string) // target -> []sources
	for _, op := range ops {
		targetMap[op.Target] = append(targetMap[op.Target], op.Source)
	}
	for target, sources := range targetMap {
		if len(sources) > 1 {
			// Find all ops with this target, in sorted order
			var conflictOps []RenameOp
			for _, op := range ops {
				if op.Target == target {
					conflictOps = append(conflictOps, op)
				}
			}
			return "same_name", conflictOps
		}
	}

	// Check for existing file conflicts
	for _, op := range ops {
		_, err := os.Stat(op.Target)
		if err == nil {
			// Target exists
			return "existing", []RenameOp{op}
		}
	}

	return "", nil
}

func processRegex(re *regexp.Regexp, replacement string, paths []string, cfg Config) {
	isDryRun := !cfg.Force

	if !cfg.Silent {
		if isDryRun {
			printDryRunHeader(cfg.Colored)
		}
	}

	allPaths := collectPaths(paths, cfg)
	var ops []RenameOp

	for _, path := range allPaths {
		filename := filepath.Base(path)
		newFilename, ok := computeNewName(re, filename, replacement, cfg.ReplaceLimit, cfg.Transform)
		if !ok {
			continue
		}

		dir := filepath.Dir(path)
		var newPath string
		if dir == "." {
			newPath = newFilename
		} else {
			newPath = filepath.Join(dir, newFilename)
		}

		ops = append(ops, RenameOp{Source: path, Target: newPath})
	}

	// Check for conflicts
	conflictType, conflictOps := checkConflicts(ops)
	if conflictType == "same_name" {
		fmt.Printf("Error: Files will have the same name\n\n")
		for _, op := range conflictOps {
			fmt.Printf("%s->%s\n", op.Source, op.Target)
		}
		fmt.Println()
		os.Exit(1)
	}
	if conflictType == "existing" {
		fmt.Printf("Error: Conflict with existing path %s -> %s\n", conflictOps[0].Source, conflictOps[0].Target)
		os.Exit(1)
	}

	// Perform operations
	var successOps []Operation

	for _, op := range ops {
		path := op.Source
		newPath := op.Target
		filename := filepath.Base(path)
		newFilename := filepath.Base(newPath)

		if cfg.Force && cfg.Backup {
			bkPath, err := backupFile(path)
			if err == nil && !cfg.Silent {
				printBackupInfo(path, bkPath, cfg.Colored)
			}
		}

		if !cfg.Silent {
			if cfg.Colored {
				srcParent := pathParent(path)
				dstParent := pathParent(newPath)
				coloredDest := colorizeFilenameDest(re, filename, replacement, cfg.ReplaceLimit)
				fmt.Printf("%s%s -> %s%s\n",
					darkGray(srcParent), darkGray(filename),
					green(dstParent), coloredDest)
			} else {
				fmt.Printf("%s -> %s\n", path, newPath)
			}
		}

		if cfg.Force {
			os.Rename(path, newPath)
		}

		successOps = append(successOps, Operation{Source: path, Target: newPath})
	}

	shouldDump := !cfg.NoDump && (cfg.Dump || cfg.Force)
	if shouldDump && len(successOps) > 0 {
		writeDump(cfg.DumpPrefix, successOps)
	}
}

func processFromFile(dumpfile string, cfg Config) {
	data, err := os.ReadFile(dumpfile)
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error: %v\n", err)
		return
	}

	var dumpData DumpFile
	if err := json.Unmarshal(data, &dumpData); err != nil {
		fmt.Fprintf(os.Stderr, "Error: %v\n", err)
		return
	}

	isDryRun := !cfg.Force
	if !cfg.Silent && isDryRun {
		printDryRunHeader(cfg.Colored)
	}

	var newOps []Operation

	for _, op := range dumpData.Operations {
		src, dst := op.Source, op.Target
		if cfg.Undo {
			src, dst = dst, src
		}

		if cfg.Force && cfg.Backup {
			bkPath, err := backupFile(src)
			if err == nil && !cfg.Silent {
				printBackupInfo(src, bkPath, cfg.Colored)
			}
		}

		if !cfg.Silent {
			if cfg.Colored {
				srcParent := pathParent(src)
				dstParent := pathParent(dst)
				srcBase := filepath.Base(src)
				dstBase := filepath.Base(dst)
				fmt.Printf("%s%s -> %s%s\n",
					darkGray(srcParent), darkGray(srcBase),
					green(dstParent), green(dstBase))
			} else {
				fmt.Printf("%s -> %s\n", src, dst)
			}
		}

		if cfg.Force {
			os.Rename(src, dst)
		}

		newOps = append(newOps, Operation{Source: src, Target: dst})
	}

	shouldDump := !cfg.NoDump && (cfg.Dump || cfg.Force)
	if shouldDump && len(newOps) > 0 {
		writeDump(cfg.DumpPrefix, newOps)
	}
}

func processToAscii(paths []string, cfg Config) {
	isDryRun := !cfg.Force
	if !cfg.Silent && isDryRun {
		printDryRunHeader(cfg.Colored)
	}

	allPaths := collectPaths(paths, cfg)
	var ops []RenameOp

	for _, path := range allPaths {
		filename := filepath.Base(path)
		newFilename := toAscii(filename)
		if newFilename == filename {
			continue
		}

		dir := filepath.Dir(path)
		var newPath string
		if dir == "." {
			newPath = newFilename
		} else {
			newPath = filepath.Join(dir, newFilename)
		}

		ops = append(ops, RenameOp{Source: path, Target: newPath})
	}

	// Check for conflicts
	conflictType, conflictOps := checkConflicts(ops)
	if conflictType == "same_name" {
		fmt.Printf("Error: Files will have the same name\n\n")
		for _, op := range conflictOps {
			fmt.Printf("%s->%s\n", op.Source, op.Target)
		}
		fmt.Println()
		os.Exit(1)
	}
	if conflictType == "existing" {
		fmt.Printf("Error: Conflict with existing path %s -> %s\n", conflictOps[0].Source, conflictOps[0].Target)
		os.Exit(1)
	}

	var successOps []Operation

	for _, op := range ops {
		path := op.Source
		newPath := op.Target
		filename := filepath.Base(path)
		newFilename := filepath.Base(newPath)

		if cfg.Force && cfg.Backup {
			bkPath, err := backupFile(path)
			if err == nil && !cfg.Silent {
				printBackupInfo(path, bkPath, cfg.Colored)
			}
		}

		if !cfg.Silent {
			if cfg.Colored {
				srcParent := pathParent(path)
				dstParent := pathParent(newPath)
				fmt.Printf("%s%s -> %s%s\n",
					darkGray(srcParent), darkGray(filename),
					green(dstParent), green(newFilename))
			} else {
				fmt.Printf("%s -> %s\n", path, newPath)
			}
		}

		if cfg.Force {
			os.Rename(path, newPath)
		}

		successOps = append(successOps, Operation{Source: path, Target: newPath})
	}

	shouldDump := !cfg.NoDump && (cfg.Dump || cfg.Force)
	if shouldDump && len(successOps) > 0 {
		writeDump(cfg.DumpPrefix, successOps)
	}
}

// toAscii transliterates a string to ASCII
func toAscii(s string) string {
	var result strings.Builder
	for _, r := range s {
		if r < 128 {
			result.WriteRune(r)
			continue
		}
		ascii := unicodeToAscii(r)
		result.WriteString(ascii)
	}
	return result.String()
}

