type Args struct {
	Subcommand   string
	Expression   string
	Replacement  string
	Paths        []string
	Force        bool
	Backup       bool
	Silent       bool
	ColorMode    string
	Dump         bool
	NoDump       bool
	DumpPrefix   string
	ReplaceLimit int
	Transform    string
	IncludeDirs  bool
	Recursive    bool
	MaxDepth     int
	Hidden       bool
	DumpFile     string
	Undo         bool
}

func parseRegexArgs(res Args, args []string) Args {
	var positional []string

	i := 0
	for i < len(args) {
		arg := args[i]
		switch arg {
		case "-n", "--dry-run":
		case "-f", "--force":
			res.Force = true
		case "-b", "--backup":
			res.Backup = true
		case "-s", "--silent":
			res.Silent = true
		case "--color":
			i++
			if i < len(args) {
				res.ColorMode = args[i]
			}
		case "--dump":
			if res.NoDump {
				fmt.Fprintf(os.Stderr, "error: the argument '--dump' cannot be used with '--no-dump'\n\nUsage: rnr regex --dump <EXPRESSION> <REPLACEMENT> <PATH(S)>...\n\nFor more information, try '--help'.\n")
				os.Exit(2)
			}
			res.Dump = true
		case "--no-dump":
			if res.Dump {
				fmt.Fprintf(os.Stderr, "error: the argument '--dump' cannot be used with '--no-dump'\n\nUsage: rnr regex --dump <EXPRESSION> <REPLACEMENT> <PATH(S)>...\n\nFor more information, try '--help'.\n")
				os.Exit(2)
			}
			res.NoDump = true
		case "--dump-prefix":
			i++
			if i < len(args) {
				res.DumpPrefix = args[i]
			}
		case "-l", "--replace-limit":
			i++
			if i < len(args) {
				fmt.Sscanf(args[i], "%d", &res.ReplaceLimit)
			}
		case "-t", "--replace-transform":
			i++
			if i < len(args) {
				res.Transform = args[i]
			}
		case "-D", "--include-dirs":
			res.IncludeDirs = true
		case "-r", "--recursive":
			res.Recursive = true
		case "-d", "--max-depth":
			i++
			if i < len(args) {
				fmt.Sscanf(args[i], "%d", &res.MaxDepth)
			}
		case "-x", "--hidden":
			res.Hidden = true
		case "-h", "--help":
			printRegexHelp()
			os.Exit(0)
		default:
			if strings.HasPrefix(arg, "--color=") {
				res.ColorMode = arg[8:]
			} else if strings.HasPrefix(arg, "--dump-prefix=") {
				res.DumpPrefix = arg[14:]
			} else if strings.HasPrefix(arg, "--replace-limit=") {
				fmt.Sscanf(arg[16:], "%d", &res.ReplaceLimit)
			} else if strings.HasPrefix(arg, "--replace-transform=") {
				res.Transform = arg[20:]
			} else if strings.HasPrefix(arg, "--max-depth=") {
				fmt.Sscanf(arg[12:], "%d", &res.MaxDepth)
			} else if len(arg) > 2 && arg[0] == '-' && arg[1] != '-' {
				// Handle combined short flags like -l1
				flag := arg[1:2]
				value := arg[2:]
				switch flag {
				case "l":
					fmt.Sscanf(value, "%d", &res.ReplaceLimit)
				case "t":
					res.Transform = value
				case "d":
					fmt.Sscanf(value, "%d", &res.MaxDepth)
				default:
					positional = append(positional, arg)
				}
			} else {
				positional = append(positional, arg)
			}
		}
		i++
	}

	if len(positional) < 2 {
		fmt.Fprintf(os.Stderr, "error: missing required arguments\n")
		os.Exit(2)
	}

	res.Expression = positional[0]
	res.Replacement = positional[1]
	res.Paths = positional[2:]

	if len(res.Paths) == 0 {
		fmt.Fprintf(os.Stderr, "error: missing required argument: <PATH(S)>\n")
		os.Exit(2)
	}

	return res
}

