func main() {
	args := os.Args[1:]
	if len(args) == 0 {
		printHelp()
		os.Exit(0)
	}

	firstArg := args[0]
	if firstArg == "--help" || firstArg == "-h" {
		printHelp()
		os.Exit(0)
	}
	if firstArg == "--version" || firstArg == "-V" {
		fmt.Printf("rnr %s\n", version)
		os.Exit(0)
	}

	res := Args{
		ColorMode:    "auto",
		DumpPrefix:   "rnr-",
		ReplaceLimit: 1,
	}
	res.Subcommand = args[0]
	remaining := args[1:]

	switch res.Subcommand {
	case "regex":
		res = parseRegexArgs(res, remaining)
	case "from-file":
		res = parseFromFileArgs(res, remaining)
	case "to-ascii":
		res = parseToAsciiArgs(res, remaining)
	case "help":
		if len(remaining) > 0 {
			switch remaining[0] {
			case "regex":
				printRegexHelp()
			case "from-file":
				printFromFileHelp()
			case "to-ascii":
				printToAsciiHelp()
			default:
				printHelp()
			}
		} else {
			printHelp()
		}
		os.Exit(0)
	default:
		fmt.Fprintf(os.Stderr, "error: unrecognized subcommand '%s'\n\nUsage: rnr <COMMAND>\n\nFor more information, try '--help'.\n", res.Subcommand)
		os.Exit(2)
	}

	cfg := Config{
		Force:        res.Force,
		Backup:       res.Backup,
		Silent:       res.Silent,
		Colored:      useColor(res.ColorMode),
		Dump:         res.Dump,
		NoDump:       res.NoDump,
		DumpPrefix:   res.DumpPrefix,
		ReplaceLimit: res.ReplaceLimit,
		Transform:    res.Transform,
		IncludeDirs:  res.IncludeDirs,
		Recursive:    res.Recursive,
		MaxDepth:     res.MaxDepth,
		Hidden:       res.Hidden,
		Undo:         res.Undo,
	}

	switch res.Subcommand {
	case "regex":
		re, err := regexp.Compile(res.Expression)
		if err != nil {
			fmt.Printf("Error: Bad expression provided\n\n%v\n", err)
			os.Exit(1)
		}
		processRegex(re, res.Replacement, res.Paths, cfg)
	case "from-file":
		processFromFile(res.DumpFile, cfg)
	case "to-ascii":
		processToAscii(res.Paths, cfg)
	}
}
